begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
create temp table cc_fx(k text primary key,id uuid,v jsonb);grant all on cc_fx to authenticated,service_role;
insert into cc_fx(k,id)select k,gen_random_uuid()from unnest(array['admin','staff','sid','staffsid','capture','cancel','policy','bad','otherpet','nulllease'])k;
create function pg_temp.cc_id(k text)returns uuid language sql as $$select id from cc_fx where cc_fx.k=$1$$;
insert into auth.users(id,email,raw_user_meta_data)select id,'synthetic-call-'||id||'@example.test','{}'from cc_fx where k in('admin','staff');update profiles set is_active=true where id in(pg_temp.cc_id('admin'),pg_temp.cc_id('staff'));insert into user_roles(user_id,role)values(pg_temp.cc_id('admin'),'ADMIN'),(pg_temp.cc_id('staff'),'STAFF')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.cc_id('sid'),pg_temp.cc_id('admin'),now(),now()),(pg_temp.cc_id('staffsid'),pg_temp.cc_id('staff'),now(),now());
select ok(relrowsecurity and not has_table_privilege('anon',oid,'SELECT')and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('service_role',oid,'SELECT'),relname||' private RLS')from pg_class where relnamespace='public'::regnamespace and relname like'clinical_call_%'and relkind='r';
select ok(has_function_privilege('service_role',oid,'EXECUTE')and not has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE'),proname||' worker only')from pg_proc where pronamespace='public'::regnamespace and proname in('dispatch_clinical_call_capture','finish_clinical_call_capture','fail_clinical_call_capture');
select ok(not has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE'),proname||' private helper')from pg_proc where pronamespace='public'::regnamespace and proname like'clinical_call_%';
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cc_id('admin'),'role','authenticated','session_id',pg_temp.cc_id('sid'))::text,true);set local role authenticated;
insert into cc_fx(k,id)select'client',id from save_client(auth.uid(),null,null,'Synthetic','Calls','+13035555583','synthetic-calls@example.test','EMAIL',null,null);
insert into cc_fx(k,id)select'pet',id from save_patient(null,pg_temp.cc_id('client'),null,'Synthetic Call Patient','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into cc_fx(k,id)select'enc',id from save_clinical_encounter(null,pg_temp.cc_id('pet'),null,now(),'clinic','Synthetic call source','','','Fictional historical assessment.','Fictional plan for local test.');
select is(read_clinical_call_policy(auth.uid())->>'status','draft','Independent call-source policy defaults draft');
reset role;
insert into cloudtalk_calls(call_uuid,call_id,direction,external_number,internal_number,started_at,ended_at,duration_seconds,talking_seconds,trusted_number,transcript_ready,last_event_at)values('synthetic-call-'||pg_temp.cc_id('capture'),'700013','inbound','+13035555583','+13035550000',now()-interval'2 minutes',now()-interval'1 minute',60,60,true,true,now());
set local role authenticated;
insert into cc_fx(k,v)select 'candidates',list_clinical_call_candidates(auth.uid(),pg_temp.cc_id('pet'),pg_temp.cc_id('enc'),1);
select is(jsonb_array_length((select v->'calls'from cc_fx where k='candidates')),1,'Exact assigned household call eligible');
select throws_ok($$select list_clinical_call_candidates(auth.uid(),pg_temp.cc_id('pet'),pg_temp.cc_id('enc'),null)$$,'PT409',null,'Null expected destination version cannot list candidates');
insert into cc_fx(k,v)select 'intent',jsonb_build_object('pet_id',pg_temp.cc_id('pet'),'expected_pet_version',1,'encounter_id',pg_temp.cc_id('enc'),'expected_encounter_version',1,'inbound_id',v#>>'{calls,0,inbound_id}','expected_inbound_version',(v#>>'{calls,0,inbound_version}')::integer,'policy_version',2,'attest_authorized',true)from cc_fx where k='candidates';
select throws_ok($$select reserve_clinical_call_capture(auth.uid(),pg_temp.cc_id('capture'),(select v from cc_fx where k='intent'))$$,'PT403',null,'Draft policy blocks capture');
select save_clinical_call_policy(auth.uid(),pg_temp.cc_id('policy'),'{"expected_version":1,"status":"approved","consent_text":"Synthetic local review only","retention_text":"Synthetic retention only","attest_reviewed":true}');
select is(recover_clinical_call_policy(auth.uid(),pg_temp.cc_id('policy'))->>'status','approved','Exact reviewed policy action recovers');
select is(cancel_clinical_call_capture(auth.uid(),pg_temp.cc_id('cancel'))->>'cancelled','true','Absent action canceled durably');
select throws_ok($$select reserve_clinical_call_capture(auth.uid(),pg_temp.cc_id('cancel'),(select v from cc_fx where k='intent'))$$,'PT409',null,'Delayed canceled capture cannot revive');
insert into cc_fx(k,id)select 'otherclient',id from save_client(auth.uid(),null,null,'Synthetic','Other Household','+13035555585','synthetic-other-calls@example.test','EMAIL',null,null);
insert into cc_fx(k,id)select 'householdpet',id from save_patient(null,pg_temp.cc_id('otherclient'),null,'Other household patient','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into cc_fx(k,id)select 'householdenc',id from save_clinical_encounter(null,pg_temp.cc_id('householdpet'),null,now(),'clinic','Other synthetic call','','','','');
select throws_ok($$select reserve_clinical_call_capture(auth.uid(),gen_random_uuid(),(select v||jsonb_build_object('pet_id',pg_temp.cc_id('householdpet'),'encounter_id',pg_temp.cc_id('householdenc'))from cc_fx where k='intent'))$$,'PT409',null,'Other household cannot capture assigned call');
select throws_ok($$select reserve_clinical_call_capture(auth.uid(),gen_random_uuid(),(select v||jsonb_build_object('pet_id',pg_temp.cc_id('householdpet'))from cc_fx where k='intent'))$$,'PT409',null,'Patient and encounter mismatch refused');
select throws_ok($$select reserve_clinical_call_capture(auth.uid(),gen_random_uuid(),(select v||'{"expected_inbound_version":999}'from cc_fx where k='intent'))$$,'PT409',null,'Stale assignment version refused');
select throws_ok($$select reserve_clinical_call_capture(auth.uid(),gen_random_uuid(),(select v||'{"context":{"call_ended_at":"2001-01-01"}}'from cc_fx where k='intent'))$$,'PT422',null,'Browser cannot override call event context');
select is(reserve_clinical_call_capture(auth.uid(),pg_temp.cc_id('capture'),(select v from cc_fx where k='intent'))#>>'{action,state}','pending','Capture reserves exact patient and unsigned encounter');
select is(reserve_clinical_call_capture(auth.uid(),pg_temp.cc_id('capture'),(select v from cc_fx where k='intent'))#>>'{action,id}',pg_temp.cc_id('capture')::text,'Duplicate reserve preserves same identity');
select throws_ok($$select reserve_clinical_call_capture(auth.uid(),pg_temp.cc_id('capture'),(select v||'{"policy_version":1}'from cc_fx where k='intent'))$$,'PT409',null,'One action cannot change intent');
reset role;set local role service_role;
select is(dispatch_clinical_call_capture(pg_temp.cc_id('capture'))->>'provider_call_id','700013','Dispatch derives provider identity from server binding');
select is(dispatch_clinical_call_capture(pg_temp.cc_id('capture')),null,'Duplicate dispatch cannot refetch provider');
reset role;
insert into cc_fx(k,v)select 'document',jsonb_build_object('contract_version','clinical-call-source-v1','provider_schema_version','cloudtalk-ci-transcription-v1','completeness','observed_two_pass','call_id','700013','language','en','callers','[{"type":"contact","id":null,"localIdentifier":"speaker-1"}]'::jsonb,'segments',jsonb_build_array(jsonb_build_object('ordinal',1,'start',0,'end',2,'caller','speaker-1','text','Owner: vaccine declined.','text_sha256',encode(extensions.digest(convert_to('Owner: vaccine declined.','UTF8'),'sha256'),'hex'),'projection_from',0,'projection_to',length(E'[#0001 caller="speaker-1"]\nOwner: vaccine declined.\n'))),'projection',E'[#0001 caller="speaker-1"]\nOwner: vaccine declined.\n','captured_from',now()-interval'1 second','captured_until',now(),'pages',jsonb_build_array(jsonb_build_object('pass',1,'offset',0,'limit',100,'total',1,'count',1,'sha256',repeat('a',64),'retrieved_at',now()),jsonb_build_object('pass',2,'offset',0,'limit',100,'total',1,'count',1,'sha256',repeat('a',64),'retrieved_at',now())));
update cc_fx set v=jsonb_set(v,'{pages}',(select jsonb_agg(pg||jsonb_build_object('normalized_json',normalized,'sha256',encode(extensions.digest(convert_to(normalized,'UTF8'),'sha256'),'hex'))order by ord)from jsonb_array_elements(v->'pages')with ordinality t(pg,ord)cross join lateral(select jsonb_build_object('data',jsonb_build_object('callId',700013,'language','en','callers',v->'callers','segments',(select jsonb_agg(x-array['ordinal','text_sha256','projection_from','projection_to'])from jsonb_array_elements(v->'segments')x)),'pagination',jsonb_build_object('offset',0,'limit',100,'total',1))::text normalized)n))where k='document';
set local role authenticated;select reserve_clinical_call_capture(auth.uid(),pg_temp.cc_id('nulllease'),(select v from cc_fx where k='intent'));reset role;set local role service_role;select dispatch_clinical_call_capture(pg_temp.cc_id('nulllease'));reset role;
-- Deliberate owned-fixture corruption: no valid worker path can create this missing lease.
update clinical_call_capture_actions set lease_until=null where id=pg_temp.cc_id('nulllease');set local role service_role;
select throws_ok($$select finish_clinical_call_capture(pg_temp.cc_id('nulllease'),(select v from cc_fx where k='document'))$$,'PT409',null,'Null capturing lease cannot finish even with otherwise valid evidence');
reset role;select is((select count(*)::integer from clinical_call_sources where capture_id=pg_temp.cc_id('nulllease')),0,'Null lease retained no source');set local role authenticated;
select is(read_clinical_call_capture(auth.uid(),pg_temp.cc_id('nulllease'))#>>'{action,state}','failed','Recovery terminates a null lease without retrying provider access');reset role;
set local role service_role;
select throws_ok($$select finish_clinical_call_capture(pg_temp.cc_id('capture'),(select jsonb_set(v,'{segments,0,text_sha256}',to_jsonb(repeat('b',64)))from cc_fx where k='document'))$$,'PT422',null,'Segment hash mismatch rejected');
select throws_ok($$select finish_clinical_call_capture(pg_temp.cc_id('capture'),(select jsonb_set(v,'{pages,1,offset}','1')from cc_fx where k='document'))$$,'PT422',null,'Page gap rejected');
select is(finish_clinical_call_capture(pg_temp.cc_id('capture'),(select v from cc_fx where k='document'))->>'retained','true','Complete observed source retained privately');
select is(finish_clinical_call_capture(pg_temp.cc_id('capture'),(select v from cc_fx where k='document'))->>'retained','true','Lost finish acknowledgement recovers exact source');
select throws_ok($$select finish_clinical_call_capture(pg_temp.cc_id('capture'),(select v||'{"language":"fr"}'from cc_fx where k='document'))$$,'PT409',null,'Changed completed source refused');
reset role;set local role authenticated;
select is(read_clinical_call_capture(auth.uid(),pg_temp.cc_id('capture'))#>>'{source,document,segments,0,text}','Owner: vaccine declined.','Current administrator reads original frozen evidence');
select is(jsonb_array_length(list_clinical_call_sources(auth.uid(),pg_temp.cc_id('pet'))->'sources'),1,'Private source list scoped to selected patient');
select is(read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))->>'id',pg_temp.cc_id('capture')::text,'Direct private source read preserves identity');
select is((read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))#>>'{context,call_ended_at}')::timestamptz,(select ended_at from cloudtalk_calls where call_uuid='synthetic-call-'||pg_temp.cc_id('capture')),'Call event time retained separately from capture time');
reset role;
select is((select sha256 from clinical_call_sources where id=pg_temp.cc_id('capture')),(select public.clinical_recap_hash(jsonb_build_object('context',context,'document',document))from clinical_call_sources where id=pg_temp.cc_id('capture')),'Source manifest hash includes immutable event context and transcript');
set local role authenticated;
reset role;
select is((select count(*)::integer from clinical_note_jobs where pet_id=pg_temp.cc_id('pet')),0,'Capture creates no AI note job');
select is((select subjective from clinical_encounters where id=pg_temp.cc_id('enc')),'','Capture never writes chart');
select throws_ok($$update clinical_call_sources set sha256=repeat('a',64)where id=pg_temp.cc_id('capture')$$,'23514',null,'Retained call source immutable');
update cloudtalk_calls set ended_at=ended_at+interval'10 seconds',last_event_at=clock_timestamp()where call_uuid='synthetic-call-'||pg_temp.cc_id('capture');set local role authenticated;
select isnt((read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))#>>'{context,call_ended_at}')::timestamptz,(select ended_at from cloudtalk_calls where call_uuid='synthetic-call-'||pg_temp.cc_id('capture')),'Later provider event does not rewrite retained call time');
reset role;update cloudtalk_calls set call_id='700014'where call_uuid='synthetic-call-'||pg_temp.cc_id('capture');set local role authenticated;
select throws_ok($$select read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))$$,'PT403',null,'Changed current provider identity blocks retained source read');
reset role;update cloudtalk_calls set call_id='700013'where call_uuid='synthetic-call-'||pg_temp.cc_id('capture');
update auth.users set banned_until=clock_timestamp()+interval'1 day'where id=pg_temp.cc_id('admin');set local role authenticated;
select throws_ok($$select read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))$$,'42501',null,'Banned admin with present session cannot read retained source');
select throws_ok($$select read_clinical_call_capture(auth.uid(),pg_temp.cc_id('capture'))$$,'42501',null,'Banned admin cannot recover call transcript');
select throws_ok($$select list_clinical_call_sources(auth.uid(),pg_temp.cc_id('pet'))$$,'42501',null,'Banned admin cannot list private source history');
select throws_ok($$select read_clinical_call_policy(auth.uid())$$,'42501',null,'Banned admin cannot use call policy RPC');
reset role;update auth.users set banned_until=null where id=pg_temp.cc_id('admin');
update cloudtalk_calls set trusted_number=false where call_uuid='synthetic-call-'||pg_temp.cc_id('capture');set local role authenticated;
select throws_ok($$select read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))$$,'PT403',null,'Revoked call trust blocks direct source read');
select is(jsonb_array_length(list_clinical_call_sources(auth.uid(),pg_temp.cc_id('pet'))->'sources'),0,'Revoked call trust is filtered before history pagination');
select throws_ok($$select read_clinical_call_capture(auth.uid(),pg_temp.cc_id('capture'))$$,'PT403',null,'Revoked call trust blocks capture recovery');
reset role;update cloudtalk_calls set trusted_number=true where call_uuid='synthetic-call-'||pg_temp.cc_id('capture');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cc_id('staff'),'role','authenticated','session_id',pg_temp.cc_id('staffsid'))::text,true);set local role authenticated;
select throws_ok($$select read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))$$,'PT403',null,'Staff cannot read source through guessed ID');
select throws_ok($$select read_clinical_call_capture(auth.uid(),pg_temp.cc_id('capture'))$$,'PT403',null,'Staff recovery cannot reveal call source');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cc_id('admin'),'role','authenticated','session_id',pg_temp.cc_id('sid'))::text,true);set local role authenticated;
select sign_clinical_encounter(pg_temp.cc_id('enc'),1);
select throws_ok($$select reserve_clinical_call_capture(auth.uid(),gen_random_uuid(),(select v from cc_fx where k='intent'))$$,'PT409',null,'Signed destination cannot capture a new source');
select is(read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))->>'id',pg_temp.cc_id('capture')::text,'Signed destination does not erase authorized historical evidence');
reset role;
delete from auth.sessions where id=pg_temp.cc_id('sid');select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.cc_id('admin'),'role','authenticated','session_id',pg_temp.cc_id('sid'))::text,true);set local role authenticated;
select throws_ok($$select read_clinical_call_source(auth.uid(),pg_temp.cc_id('capture'))$$,'42501',null,'Revoked admin session cannot read retained call');
select *from finish();rollback;
